class Solution {
public:
    int minTimeToReach(vector<vector<int>>& moveTime) {
        int n = moveTime.size();
        int m = moveTime[0].size();
        vector<vector<int>> dist(n, vector<int>(m, 1e9 + 7));
        dist[0][0] = 0;

        using State = tuple<int, int, int>;
        priority_queue<State, vector<State>, greater<State>> pq;
        pq.push({0, 0, 0});

        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        while (!pq.empty()) {
            auto [t, r, c] = pq.top();
            pq.pop();
            if (r == n - 1 && c == m - 1) return t;
            if (t > dist[r][c]) continue;

            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                    int nt = max(t, moveTime[nr][nc]) + 1;
                    if (nt < dist[nr][nc]) {
                        dist[nr][nc] = nt;
                        pq.push({nt, nr, nc});
                    }
                }
            }
        }
        return -1;
    }
};

class Solution {
    public int minTimeToReach(int[][] moveTime) {
        int n = moveTime.length;
        int m = moveTime[0].length;
        int[][] dist = new int[n][m];
        for (int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);
        dist[0][0] = 0;

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        pq.offer(new int[]{0, 0, 0});

        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            int t = curr[0], r = curr[1], c = curr[2];
            if (r == n - 1 && c == m - 1) return t;
            if (t > dist[r][c]) continue;

            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                    int nt = Math.max(t, moveTime[nr][nc]) + 1;
                    if (nt < dist[nr][nc]) {
                        dist[nr][nc] = nt;
                        pq.offer(new int[]{nt, nr, nc});
                    }
                }
            }
        }
        return -1;
    }
}

var minTimeToReach = function(moveTime) {
    const n = moveTime.length;
    const m = moveTime[0].length;
    const dist = Array.from({ length: n }, () => new Array(m).fill(Infinity));
    dist[0][0] = 0;

    // Simple min-heap simulation with binary heap or sorted insertion
    const pq = [[0, 0, 0]];
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];

    while (pq.length > 0) {
        // Pop min element
        let minIdx = 0;
        for (let i = 1; i < pq.length; i++) {
            if (pq[i][0] < pq[minIdx][0]) minIdx = i;
        }
        const [t, r, c] = pq.splice(minIdx, 1)[0];

        if (r === n - 1 && c === m - 1) return t;
        if (t > dist[r][c]) continue;

        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                const nt = Math.max(t, moveTime[nr][nc]) + 1;
                if (nt < dist[nr][nc]) {
                    dist[nr][nc] = nt;
                    pq.push([nt, nr, nc]);
                }
            }
        }
    }
    return -1;
};
